package com.moviebooking.notification.controller;
import com.moviebooking.notification.dto.*;import com.moviebooking.notification.service.NotificationService;import io.swagger.v3.oas.annotations.*;import io.swagger.v3.oas.annotations.tags.Tag;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/notifications") @RequiredArgsConstructor @Tag(name="Notifications") public class NotificationController {private final NotificationService service;private Pageable pageable(int page,int size){return PageRequest.of(page,Math.min(size,100),Sort.by("createdAt").descending());}@GetMapping @Operation(summary="List notifications") public ApiResponse<Page<NotificationResponse>> all(@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return ApiResponse.ok("Notifications fetched successfully",service.all(pageable(page,size)));}@GetMapping("/{id}") public ApiResponse<NotificationResponse> one(@PathVariable Long id){return ApiResponse.ok("Notification fetched successfully",service.one(id));}@GetMapping("/user/{userId}") public ApiResponse<Page<NotificationResponse>> user(@PathVariable String userId,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return ApiResponse.ok("Notifications fetched successfully",service.user(userId,pageable(page,size)));}@GetMapping("/booking/{bookingId}") public ApiResponse<Page<NotificationResponse>> booking(@PathVariable String bookingId,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return ApiResponse.ok("Notifications fetched successfully",service.booking(bookingId,pageable(page,size)));}@GetMapping("/user/{userId}/unread") public ApiResponse<Page<NotificationResponse>> unread(@PathVariable String userId,@RequestParam(defaultValue="0") int page,@RequestParam(defaultValue="10") int size){return ApiResponse.ok("Unread notifications fetched successfully",service.unread(userId,pageable(page,size)));}@PatchMapping("/{id}/read") public ApiResponse<NotificationResponse> read(@PathVariable Long id){return ApiResponse.ok("Notification marked as read",service.markRead(id));}@PatchMapping("/user/{userId}/read-all") public ApiResponse<Integer> readAll(@PathVariable String userId){return ApiResponse.ok("Notifications marked as read",service.markAllRead(userId));}}
